using System.IO;
using FontFilter;
using System.Diagnostics;
if(args.Length==2&&args[0]=="--refresh-index"){using var db=new FontStore(Path.Combine(args[1],"fonts.db"));using var scanner=new FontScanner();db.RefreshRuleTags();var scan=scanner.ScanAsync(db,new Progress<ScanProgress>(),CancellationToken.None).GetAwaiter().GetResult();Console.WriteLine($"REFRESH faces={scan.Faces}, errors={scan.Errors}, complete={scan.Complete}");return scan.Complete&&scan.Errors==0?0:1;}
if(args.Length==2&&args[0]=="--import-official"){var catalogue=OfficialCatalogue.Load(Path.Combine(args[1],"official-fonts.json"));using var db=new FontStore(Path.Combine(args[1],"fonts.db"));var matches=OfficialCatalogue.Match(db.All(),catalogue.Records);var result=db.ImportOfficial(matches);Console.WriteLine($"OFFICIAL matchedFaces={matches.Count}, added={result.Added}, preserved={result.Existing}, withoutDescription={result.WithoutDescription}");return 0;}
if(args.Length==2&&args[0]=="--attach-tags"){using var store=new FontStore(Path.Combine(args[1],"fonts.db"));var cat=OfficialCatalogue.Load(Path.Combine(args[1],"official-fonts.json"));Console.WriteLine("ATTACHED "+store.AttachOfficialTags(OfficialCatalogue.Match(store.All(),cat.Records)));return 0;}
var failures=0; var count=0;
void Test(string name,Action test){count++;try{test();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Check(bool ok,string why){if(!ok)throw new Exception(why);}
var dir=Path.Combine(Path.GetTempPath(),"FontFilter-tests-"+Guid.NewGuid());Directory.CreateDirectory(dir);
using(var db=new FontStore(Path.Combine(dir,"fonts.db"))){
var a=new FontRecord("a","测试圆黑","Regular","a.ttf","方正");var b=new FontRecord("b","测试圆黑","Bold","b.ttf","方正");
Test("family retains distinct weights",()=>{db.Upsert(a);db.Upsert(b);Check(db.All().Count==2,"expected two faces");});
Test("manual survives rescan",()=>{db.SetManual(new[]{"a"},"风骨 古籍");db.Upsert(a);Check(db.All().Single(x=>x.Id=="a").ManualTags.Contains("古籍"),"lost manual tag");});
Test("metadata does not overwrite manual tags",()=>{db.SaveMetadata("a","圆润柔和，适合儿童标题","https://www.foundertype.com/example");Check(db.All().Single(x=>x.Id=="a").ManualTags.Contains("风骨"),"manual overwritten");});
Test("multi-term intersection and source matching",()=>{Check(db.Search("风骨 古籍").Count==1,"AND failed");Check(db.Search("风骨 不存在").Count==0,"unmatched term ignored");Check(db.Search("方正").Count==2,"vendor not searched");});
Test("query treats SQL wildcard literally",()=>Check(db.Search("%_").Count==0,"wildcards unexpectedly expanded"));
Test("persistence",()=>{using var other=new FontStore(Path.Combine(dir,"fonts.db"));Check(other.All().Count==2,"records not persisted");});
Test("3000 record query benchmark",()=>{for(int i=0;i<3000;i++)db.Upsert(new FontRecord("p"+i,"性能字体"+i,"Regular","font.ttf","汉仪"));var sw=Stopwatch.StartNew();var result=db.Search("性能 汉仪");sw.Stop();Console.WriteLine($"BENCH {result.Count} records {sw.Elapsed.TotalMilliseconds:F1} ms");Check(result.Count==3000,"wrong result count");Check(sw.ElapsedMilliseconds<200,"query exceeded 200ms");});
}
Test("official tags attach across weights and survive metadata and rescan",()=>{using var s=new FontStore(Path.Combine(dir,"attached.db"));var f=new FontRecord("one","测试字体","Regular","a","");s.Upsert(f);s.Upsert(f with{Id="two",Face="Bold"});s.SaveMetadata("one","原有介绍","");s.SetManual(new[]{"one"},"我的标签");var source=new OfficialFontInfo{Id="fz:test",Family="测试字体",SourceUrl="https://www.foundertype.com/test",Summary="横笔画略细于竖笔画，中宫宽阔",Tags=new[]{"优雅","商务"}};Check(s.AttachOfficialTags(OfficialCatalogue.Match(s.All(),new[]{source}))==2,"not all weights attached");s.Upsert(f);s.SaveMetadata("one","保留介绍","");var one=s.All().Single(x=>x.Id=="one");Check(one.AutoTags.Contains("横细竖粗")&&one.AutoTags.Contains("中宫宽松")&&one.AutoTags.Contains("典雅")&&one.AutoTags.Contains("商务"),"missing official mapped tags");Check(one.ManualTags=="我的标签"&&one.Summary=="保留介绍","overwrote user data");Check(s.Search("商务").Count==2,"attached tags not searchable");});
Test("tag counts match search families and include official raw labels",()=>{using var s=new FontStore(Path.Combine(dir,"counts.db"));s.Upsert(new FontRecord("1","方正测试","Regular","a","方正"));s.Upsert(new FontRecord("2","方正测试","Bold","a","方正"));s.SetManual(new[]{"1","2"},"新中式");var defs=s.AvailableTagDefinitions();Check(defs.Any(t=>t.Name=="新中式"),"raw label absent");var counts=s.TagCounts(new[]{"新中式","不存在"});Check(counts["新中式"]==1&&counts["不存在"]==0,"wrong family counts");Check(counts["新中式"]==s.Search("新中式").Select(f=>f.Family).Distinct().Count(),"count differs from search");});
Test("HSB conversions preserve primaries and grayscale",()=>{var red=HsbColor.FromColor(System.Windows.Media.Colors.Red);Check(Math.Abs(red.H)<0.01&&Math.Abs(red.S-100)<0.01&&Math.Abs(red.B-100)<0.01,"red HSB incorrect");Check(HsbColor.ToColor(120,100,100)==System.Windows.Media.Colors.Lime,"green HSB incorrect");Check(HsbColor.ToColor(240,100,100)==System.Windows.Media.Colors.Blue,"blue HSB incorrect");Check(HsbColor.ToColor(360,100,100)==System.Windows.Media.Colors.Red,"hue wrap incorrect");foreach(var hex in new[]{"#7C3AED","#16594D","#808080","#000000","#FFFFFF"}){var color=(System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(hex);var hsb=HsbColor.FromColor(color);var restored=HsbColor.ToColor(hsb.H,hsb.S,hsb.B);Check(Math.Abs(restored.R-color.R)<=1&&Math.Abs(restored.G-color.G)<=1&&Math.Abs(restored.B-color.B)<=1,"HSB roundtrip lost color: "+hex);}});
Test("HSB sliders preserve hue through black and sync hexadecimal input",()=>{Exception? failure=null;var thread=new Thread(()=>{try{var window=new ThemeSettingsWindow("#FF0000");var sliders=LogicalChildren(window).OfType<System.Windows.Controls.Slider>().ToArray();Check(sliders.Length==3&&sliders[0].Maximum==360&&sliders[1].Maximum==100&&sliders[2].Maximum==100,"sliders are not HSB");sliders[2].Value=0;sliders[0].Value=240;sliders[2].Value=100;Check(window.SelectedColor=="#0000FF","hue lost at black");var hex=LogicalChildren(window).OfType<System.Windows.Controls.TextBox>().Single();hex.Text="#00FF00";Check(Math.Abs(sliders[0].Value-120)<0.1&&sliders[1].Value==100&&sliders[2].Value==100,"hex input did not update HSB");}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
Test("favorite entry stays pinned and theme changes all accent controls",()=>{Exception? failure=null;var thread=new Thread(()=>{try{var window=new MainWindow();var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var settings=(UserSettings)typeof(MainWindow).GetField("settings",flags)!.GetValue(window)!;settings.RecordTags(Enumerable.Range(0,20).Select(i=>"热门标签"+i));typeof(MainWindow).GetMethod("RenderQuickTags",flags)!.Invoke(window,null);var pinned=(System.Windows.Controls.Button)window.FindName("FavoritesFilterButton");Check(pinned.Content.ToString()!.StartsWith("★ 收藏"),"favorite entry replaced by popular tags");var content=(System.Windows.FrameworkElement)window.Content;content.Measure(new System.Windows.Size(1424,881));content.Arrange(new System.Windows.Rect(0,0,1424,881));content.UpdateLayout();Check(pinned.TranslatePoint(new System.Windows.Point(),content).Y<((System.Windows.FrameworkElement)window.FindName("QuickTagsPanel")).TranslatePoint(new System.Windows.Point(),content).Y,"favorites not pinned above tags");ThemeService.Apply(window,"#7C3AED");content.UpdateLayout();var accent=(System.Windows.Media.SolidColorBrush)window.FindResource("AccentBrush");Check(accent.Color==(System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#7C3AED"),"theme color not applied");var logo=LogicalChildren(window).OfType<LogoMark>().Single();Check(((System.Windows.Media.SolidColorBrush)logo.Accent).Color==accent.Color,"logo did not follow theme");var bitmap=LogoMark.Bitmap(128);var pixels=new byte[128*128*4];bitmap.CopyPixels(pixels,128*4,0);Check(pixels[3]==0&&pixels[(64*128+64)*4+3]==255,"logo corners are not rounded");ThemeService.Apply(window,ThemeService.DefaultColor);((FontStore)typeof(MainWindow).GetField("store",flags)!.GetValue(window)!).Dispose();}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
Test("favorites persist across family weights, rescan and restart",()=>{var path=Path.Combine(dir,"favorites.db");using(var d=new FontStore(path)){var f=new FontRecord("fav-a","测试收藏","Regular","a","");d.Upsert(f);d.Upsert(f with{Id="fav-b",Face="Bold"});d.SetFavorite(new[]{f.Family},true);Check(d.Search("",true).Count==2,"family weights not all favorited");d.Upsert(f);Check(d.Search("",true).All(x=>x.IsFavorite),"rescan lost favorite");d.MarkAbsent(new HashSet<string>());Check(d.Search("",true).Count==0,"removed fonts remain visible");d.Upsert(f);}using(var d=new FontStore(path)){Check(d.Search("",true).Single().Family=="测试收藏","favorite not restored");d.SetFavorite(new[]{"测试收藏"},false);Check(d.Search("",true).Count==0,"unfavorite failed");}});
Test("theme colors persist and choose readable foreground",()=>{Check(ThemeService.IsValid("#7C3AED")&&!ThemeService.IsValid("bad"),"invalid hex accepted");Check(ThemeService.TextColor(System.Windows.Media.Colors.White)==System.Windows.Media.Colors.Black,"light accent has light text");Check(ThemeService.TextColor(System.Windows.Media.Colors.Black)==System.Windows.Media.Colors.White,"dark accent has dark text");var settings=new UserSettings{ThemeColor="#7C3AED"};Check(System.Text.Json.JsonSerializer.Deserialize<UserSettings>(System.Text.Json.JsonSerializer.Serialize(settings))!.ThemeColor==settings.ThemeColor,"theme not persisted");});
Test("scrollbar thumb stays visible for very large font lists",()=>{Exception? failure=null;var thread=new Thread(()=>{try{var window=new System.Windows.Window();LightTheme.Apply(window);var bar=new System.Windows.Controls.Primitives.ScrollBar{Orientation=System.Windows.Controls.Orientation.Vertical,Minimum=0,Maximum=1000000,ViewportSize=300,Height=400};window.Content=bar;bar.Measure(new System.Windows.Size(16,400));bar.Arrange(new System.Windows.Rect(0,0,16,400));bar.UpdateLayout();bar.ApplyTemplate();var track=(System.Windows.Controls.Primitives.Track)bar.Template.FindName("PART_Track",bar);Check(track.Thumb.ActualHeight>=44,"scroll thumb collapsed to "+track.Thumb.ActualHeight);Check(bar.ActualWidth>=14,"scrollbar target too narrow");bar.Value=500000;bar.UpdateLayout();var point=track.Thumb.TranslatePoint(new System.Windows.Point(),bar);Check(point.Y>120&&point.Y<260,"thumb does not reflect scroll position");Check(track.ValueFromDistance(0,20)>0,"dragging cannot advance scroll position");Console.WriteLine($"SCROLLBAR thumb={track.Thumb.ActualHeight:F0}, width={bar.ActualWidth:F0}, middleY={point.Y:F0}");}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
Test("specimen UI adapts and preserves manual text",()=>{Exception? failure=null;var thread=new Thread(()=>{try{var window=new MainWindow();var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;var type=typeof(MainWindow);type.GetField("ready",flags)!.SetValue(window,true);var sample=(System.Windows.Controls.TextBox)window.FindName("SampleText");var modes=(System.Windows.Controls.ComboBox)window.FindName("SampleBox");var store=(FontStore)type.GetField("store",flags)!.GetValue(window)!;var fonts=store.All();var english=fonts.First(f=>f.Family=="Arial");type.GetField("current",flags)!.SetValue(window,english);modes.SelectedItem=FontSamples.AutoKey;type.GetMethod("ApplyAutoSample",flags)!.Invoke(window,null);Check(sample.Text==FontSamples.English,"English font did not receive English text");sample.Text="我的自定义文本 123";Check(Equals(modes.SelectedItem,FontSamples.FreeKey),"manual edit did not leave automatic mode");type.GetField("current",flags)!.SetValue(window,fonts.First(f=>f.SupportsChinese==true));type.GetMethod("ApplyAutoSample",flags)!.Invoke(window,null);Check(sample.Text=="我的自定义文本 123","font change replaced manual text");modes.SelectedItem="繁體中文";Check(sample.Text==FontSamples.Traditional,"traditional preset missing");modes.SelectedItem="简体中文";Check(sample.Text==FontSamples.Simplified,"simplified preset missing");store.Dispose();}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
Test("automatic specimen uses glyph coverage and script preference",()=>{Dictionary<int,ushort> Map(string text)=>text.EnumerateRunes().Distinct().ToDictionary(r=>r.Value,r=>(ushort)1);var latin=new FontRecord("latin","Arial","Regular","","");Check(FontSamples.Select(latin,Map(FontSamples.English)).Key=="English","Latin font got Chinese sample");var both=Map(FontSamples.Simplified+FontSamples.Traditional+FontSamples.English);Check(FontSamples.Select(latin with{Family="测试简体"},both).Key=="简体中文","default Chinese sample not simplified");Check(FontSamples.Select(latin with{Family="测试繁體"},both).Key=="繁體中文","traditional name ignored");Check(FontSamples.Select(latin with{Family="Noto Serif TC"},both).Key=="繁體中文","TC preference ignored");Check(FontSamples.Select(latin,Map(FontSamples.Traditional)).Key=="繁體中文","traditional-only coverage ignored");Check(FontSamples.Select(latin with{Family="繁体测试"},Map(FontSamples.Simplified)).Key=="简体中文","name overrode actual glyph coverage");});
Test("reopening picker and reselecting multiple tags refreshes left list",()=>{Exception? failure=null;var thread=new Thread(()=>{try{
 var window=new MainWindow();SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(window.Dispatcher));var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;var type=typeof(MainWindow);var list=(System.Windows.Controls.ListBox)window.FindName("FontList");var query=(System.Windows.Controls.TextBox)window.FindName("QueryBox");var store=(FontStore)type.GetField("store",flags)!.GetValue(window)!;
 void PumpUntil(Func<bool> condition){var frame=new System.Windows.Threading.DispatcherFrame();var watch=Stopwatch.StartNew();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(_,_)=>{if(condition()||watch.ElapsedMilliseconds>10000){timer.Stop();frame.Continue=false;}};timer.Start();System.Windows.Threading.Dispatcher.PushFrame(frame);Check(condition(),"UI did not settle; query="+query.Text+", count="+list.Items.Count);}
 window.Show();PumpUntil(()=>(bool)type.GetField("ready",flags)!.GetValue(window)!&&list.Items.Count>0);
 foreach(var tags in new[]{new[]{"宋体","中文"},new[]{"隶书","中文"},new[]{"黑体","中文"},new[]{"宋体","中文"}}){
  var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(_,_)=>{var picker=window.OwnedWindows.OfType<TagPickerWindow>().FirstOrDefault();if(picker==null)return;timer.Stop();foreach(var box in LogicalChildren(picker).OfType<System.Windows.Controls.CheckBox>())box.IsChecked=tags.Contains(System.Windows.Automation.AutomationProperties.GetName(box));LogicalChildren(picker).OfType<System.Windows.Controls.Button>().Single(b=>Equals(b.Content,"使用本次筛选")).RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));};timer.Start();type.GetMethod("TagLibrary_Click",flags)!.Invoke(window,new object[]{window,new System.Windows.RoutedEventArgs()});var expected=store.Search(string.Join(" ",tags)).Select(f=>f.Family).Distinct().Count();Check(expected>0,"bad test fixture");PumpUntil(()=>query.Text==string.Join(" ",tags)&&list.Items.Count==expected);Check(list.SelectedItem!=null,"new results have no selection");Console.WriteLine("RESELECT "+query.Text+" => "+list.Items.Count);
 }
 window.Close();PumpUntil(()=>(bool)type.GetField("closed",flags)!.GetValue(window)!);
}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
Test("picker search replaces previous filters but manual tags merge",()=>{Check(TagRules.SelectionText("宋体 古籍",new[]{"隶书"},true)=="隶书","previous filters accumulated");Check(TagRules.SelectionText("隶书",new[]{"隶书"},true)=="隶书","repeated filter duplicated");Check(TagRules.SelectionText("古籍",new[]{"隶书"},false)=="古籍 隶书","manual tags overwritten");});
Test("tag picker cells align labels and counts",()=>{Exception? failure=null;var thread=new Thread(()=>{try{var window=new TagPickerWindow(new[]{new TagDefinition("测试","宋体","宋体"),new TagDefinition("测试","横细竖粗","横细竖粗")},new Dictionary<string,int>{{"宋体",129},{"横细竖粗",19}});var boxes=LogicalChildren(window).OfType<System.Windows.Controls.CheckBox>().ToArray();Check(boxes.Length==2,"missing tags");Check(boxes.All(b=>double.IsFinite(b.Width)&&b.Width==boxes[0].Width&&b.VerticalContentAlignment==System.Windows.VerticalAlignment.Center),"uneven cells");foreach(var box in boxes){Check(box.Content is System.Windows.Controls.Grid,"name/count not laid out independently");var grid=(System.Windows.Controls.Grid)box.Content;Check(grid.Children.OfType<System.Windows.Controls.TextBlock>().Count()==2,"missing label/count");}var content=(System.Windows.FrameworkElement)window.Content;content.Measure(new System.Windows.Size(864,681));content.Arrange(new System.Windows.Rect(0,0,864,681));content.UpdateLayout();foreach(var box in boxes){var labels=((System.Windows.Controls.Grid)box.Content).Children.OfType<System.Windows.Controls.TextBlock>().ToArray();Check(Math.Abs(labels[0].TranslatePoint(new System.Windows.Point(),content).Y-labels[1].TranslatePoint(new System.Windows.Point(),content).Y)<1,"name/count baselines differ");}var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(864,681,96,96,System.Windows.Media.PixelFormats.Pbgra32);var background=new System.Windows.Media.DrawingVisual();using(var drawing=background.RenderOpen())drawing.DrawRectangle(window.Background,null,new System.Windows.Rect(0,0,864,681));bitmap.Render(background);bitmap.Render(content);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using var file=File.Create(Path.Combine(Path.GetTempPath(),"fontfilter-aligned-tags.png"));encoder.Save(file);}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
Test("frequent tags persist and sort by use",()=>{var settings=new UserSettings();settings.RecordTags(new[]{"隶书","古籍","隶书"});settings.RecordTags(new[]{"古籍"});Check(settings.FrequentTags().First()=="古籍","not ranked by frequency");var restored=System.Text.Json.JsonSerializer.Deserialize<UserSettings>(System.Text.Json.JsonSerializer.Serialize(settings))!;Check(restored.FrequentTags().Contains("隶书"),"usage not persisted");});
