if(args.Contains("--integration")){
 Test("scan actual installed fonts and incremental rescan",()=>{
 using var real=new FontStore(Path.Combine(App.DataDirectory,"fonts.db"));using var scanner=new FontScanner();var scanWatch=Stopwatch.StartNew();var first=scanner.ScanAsync(real,new Progress<ScanProgress>(),CancellationToken.None).GetAwaiter().GetResult();Check(first.Complete&&first.Faces>0,"no fonts scanned");Console.WriteLine($"FIRST_SCAN {scanWatch.Elapsed.TotalMilliseconds:F0} ms");scanWatch.Restart();var again=scanner.ScanAsync(real,new Progress<ScanProgress>(),CancellationToken.None).GetAwaiter().GetResult();Check(again.Reused>0,"incremental rescan did not reuse cache");Check(again.Reused<=again.Faces,"reuse counter exceeds unique faces");Console.WriteLine($"RESCAN {scanWatch.Elapsed.TotalMilliseconds:F0} ms");Console.WriteLine($"ACTUAL fonts={first.Faces}, families={first.Families}, errors={first.Errors}, reused={again.Reused}");
 var stored=real.All();Check(stored.Any(f=>f.Family.Contains("Arial")),"expected system font missing");
 });
