Test("metadata UI snapshot saves across worker boundary",()=>{Exception? failure=null;var thread=new Thread(()=>{try{var font=new FontRecord("ui","界面字体","Regular","file:///a.ttf","");using var db=new FontStore(Path.Combine(dir,"ui.db"));db.Upsert(font);var dialog=new MetadataWindow(font);var dock=(System.Windows.Controls.DockPanel)dialog.Content;var body=dock.Children.OfType<System.Windows.Controls.TextBox>().Single();body.Text="圆润柔和，中宫宽松";dialog.SaveToAsync(db,font.Id).GetAwaiter().GetResult();Check(db.All().Single().Summary==body.Text,"UI metadata not saved");}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
Test("response body stalls time out without metadata changes",()=>{using var listener=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);listener.Start();var endpoint=(System.Net.IPEndPoint)listener.LocalEndpoint;using var cts=new CancellationTokenSource(TimeSpan.FromSeconds(5));var server=Task.Run(async()=>{using var client=await listener.AcceptTcpClientAsync(cts.Token);await using var stream=client.GetStream();var buffer=new byte[4096];await stream.ReadAsync(buffer,cts.Token);await stream.WriteAsync(System.Text.Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: 1000\r\n\r\n"),cts.Token);try{await Task.Delay(3000,cts.Token);}catch(OperationCanceledException){}});using var http=new System.Net.Http.HttpClient();var sw=Stopwatch.StartNew();try{OfficialMetadataService.DownloadAsync(http,new Uri($"http://127.0.0.1:{endpoint.Port}/"),TimeSpan.FromMilliseconds(200),CancellationToken.None).GetAwaiter().GetResult();throw new Exception("stalled download unexpectedly succeeded");}catch(OperationCanceledException){Check(sw.ElapsedMilliseconds<2000,"body timeout exceeded");}cts.Cancel();try{server.GetAwaiter().GetResult();}catch(OperationCanceledException){} });
Test("window can close without active scan",()=>{Exception? failure=null;var thread=new Thread(()=>{var dispatcher=System.Windows.Threading.Dispatcher.CurrentDispatcher;var frame=new System.Windows.Threading.DispatcherFrame();dispatcher.UnhandledException+=(_,e)=>{failure=e.Exception;e.Handled=true;frame.Continue=false;};try{var window=new MainWindow();window.Show();window.Close();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};timer.Tick+=(_,_)=>{timer.Stop();try{Check(!window.IsVisible,"window remained open");}catch(Exception ex){failure=ex;}frame.Continue=false;};timer.Start();System.Windows.Threading.Dispatcher.PushFrame(frame);}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
