itmapFrame.Create(bitmap));using var file=File.Create(Path.Combine(App.DataDirectory,"..","proof",$"workspace-{size.Width}.png"));png.Save(file);}}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
