Test("official import adds blank descriptions without changing user data",()=>{using var d=new FontStore(Path.Combine(dir,"official.db"));var a=new FontRecord("a","测试简","Regular","a","");var b=new FontRecord("b","已有资料","Regular","b","");d.Upsert(a);d.Upsert(b);d.SetManual(new[]{"a","b"},"人工风骨");d.SaveMetadata("b","用户整理的介绍","https://www.hanyi.com.cn/productdetail?id=2");var source=new OfficialFontInfo{Id="hy:1",Family="测试",Summary="圆润柔和",Tags=new[]{"清雅"},SourceUrl="https://www.hanyi.com.cn/productdetail?id=1"};var result=d.ImportOfficial(new[]{new OfficialMatch(a,source,"名称"),new OfficialMatch(b,source,"名称")});Check(result.Added==1&&result.Existing==1,"wrong import counts");var items=d.All();Check(items.Single(x=>x.Id=="a").Summary.Contains("圆润")&&items.All(x=>x.ManualTags=="人工风骨"),"manual tags lost");Check(items.Single(x=>x.Id=="b").Summary=="用户整理的介绍","existing description overwritten");Check(d.Search("清雅").Any(x=>x.Id=="a"),"official tags not searchable");});
