Test("official cache window loads and renders offline",()=>{Exception? failure=null;var thread=new Thread(()=>{try{using var db=new FontStore(Path.Combine(App.DataDirectory,"fonts.db"));var window=new OfficialCatalogueWindow(db);SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(window.Dispatcher));var grid=LogicalChildren(window).OfType<System.Windows.Controls.DataGrid>().Single();window.Show();var frame=new System.Windows.Threading.DispatcherFrame();var sw=Stopwatch.StartNew();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(50)};timer.Tick+=(_,_)=>{if(grid.Items.Count>0||sw.ElapsedMilliseconds>5000){timer.Stop();frame.Continue=false;}};timer.Start();System.Windows.Threading.Dispatcher.PushFrame(frame);Check(grid.Items.Count>0,"offline catalogue did not load");var content=(System.Windows.FrameworkElement)window.Content;content.Measure(new System.Windows.Size(1024,701));content.Arrange(new System.Windows.Rect(0,0,1024,701));content.UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(1024,701,96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(content);var png=new System.Windows.Media.Imaging.PngBitmapEncoder();png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));Directory.CreateDirectory(Path.Combine(App.DataDirectory,"..","proof"));using(var file=File.Create(Path.Combine(App.DataDirectory,"..","proof","official-library.png")))png.Save(file);window.Close();}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;});
